const PALETTE = {
  'space-deep': 0x20283D,
  'shadow-plum': 0x765768,
  'regolith-mid': 0xB95C40,
  'regolith-light': 0xE6A26A,
  'structure-white': 0xF2E5D2,
  'structure-gray': 0x686976,
  'trim-dark': 0x303240,
  'accent-orange': 0xFF8A24,
  'accent-cyan': 0x54E5F5,
  'accent-blue': 0x35CFFF,
  'glass-tint': 0xEBD9C5,
  'cell-blue': 0x2F58B8
};

const BUDGETS = {"small-prop":1500,"medium-prop":6000,"vehicle":9000,"building":12000,"character":8000,"rock":400};
const SEGMENTS = {"small":8,"default":12,"large":16};

// Bevel radius for roundedBoxGeo: ratio of the smallest dimension (style range 0.06-0.12).
function bevel(w, h, d, ratio = 0.09) {
  return Math.min(w, h, d) * ratio;
}

// One shared material per role. Variants (e.g. structure-gray) take an explicit colour token.
function styleMaterials() {
  const m = {"matte-environment":{"description":"Terrain, rocks, craters, mountains. Fully matte, no reflections.","colors":["regolith-mid","regolith-light","shadow-plum"],"roughness":0.95,"metalness":0},"smooth-structure":{"description":"Buildings, modules, vehicles, suits, crates. Clean satin finish, never mirror-like.","colors":["structure-white","structure-gray"],"roughness":0.55,"metalness":0.05},"accent-paint":{"description":"Non-glowing orange colour blocking: side panels, crate faces, dome base band, suit pads, wheel hubs.","colors":["accent-orange"],"roughness":0.6,"metalness":0},"dark-trim":{"description":"Tyres, recesses, joints, vents.","colors":["trim-dark"],"roughness":0.85,"metalness":0},"emissive-warm":{"description":"Door frames, window strips, headlights. Selected surfaces only.","colors":["accent-orange"],"emissive":"accent-orange","emissiveIntensity":1.6,"roughness":0.5,"metalness":0},"emissive-cool":{"description":"Beacons, indicators, screens. Smaller and rarer than warm lights.","colors":["accent-cyan","accent-blue"],"emissive":"accent-cyan","emissiveIntensity":1.4,"roughness":0.5,"metalness":0},"glass":{"description":"Greenhouse domes, module windows. Light tint, soft highlight, see-through.","colors":["glass-tint"],"roughness":0.15,"metalness":0,"opacity":0.35},"visor":{"description":"Helmet visors and vehicle windshields. Opaque near-black, glossy, shows a soft highlight.","colors":["space-deep"],"roughness":0.12,"metalness":0.1},"solar-cell":{"description":"Solar panel cell faces. Deep blue, semi-gloss, framed by structure-white grid bars.","colors":["cell-blue"],"roughness":0.35,"metalness":0.1}};
  const make = (role, colorToken) => {
    const spec = m[role];
    const color = PALETTE[colorToken ?? spec.colors[0]];
    const name = colorToken && colorToken !== spec.colors[0] ? role + ':' + colorToken : role;
    if (role === 'glass') return glassMaterial(color, { opacity: spec.opacity, roughness: spec.roughness, metalness: spec.metalness, name });
    const opts = { roughness: spec.roughness, metalness: spec.metalness, name };
    if (spec.emissive) Object.assign(opts, { emissive: PALETTE[spec.emissive], emissiveIntensity: spec.emissiveIntensity });
    return gameMaterial(color, opts);
  };
  return {
    rock: make('matte-environment'),
    rockLight: make('matte-environment', 'regolith-light'),
    rockShadow: make('matte-environment', 'shadow-plum'),
    panel: make('smooth-structure'),
    panelGray: make('smooth-structure', 'structure-gray'),
    accent: make('accent-paint'),
    trim: make('dark-trim'),
    glowWarm: make('emissive-warm'),
    glowCool: make('emissive-cool'),
    glowBlue: make('emissive-cool', 'accent-blue'),
    glass: make('glass'),
    visor: make('visor'),
    solarCell: make('solar-cell'),
  };
}
// ---- end style header ----
function offsetPolygon(poly,d){
  return poly.map((p,i)=>{
    const a=poly[(i+poly.length-1)%poly.length],c=poly[(i+1)%poly.length];
    const u=[p[0]-a[0],p[1]-a[1]],v=[c[0]-p[0],c[1]-p[1]];
    const lu=Math.hypot(...u),lv=Math.hypot(...v);
    const n=[-u[1]/lu,u[0]/lu],m=[-v[1]/lv,v[0]/lv];
    const q=[p[0]+n[0]*d,p[1]+n[1]*d],r=[p[0]+m[0]*d,p[1]+m[1]*d];
    const den=u[0]*v[1]-u[1]*v[0];
    if(Math.abs(den)<1e-8)return q;
    const t=((r[0]-q[0])*v[1]-(r[1]-q[1])*v[0])/den;
    return [q[0]+u[0]*t,q[1]+u[1]*t];
  });
}
function geometryBuilder(){
  const pos=[];
  const tri=(a,b,c)=>pos.push(...a,...b,...c);
  const quad=(a,b,c,d)=>{tri(a,b,c);tri(a,c,d);};
  const finish=()=>{const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.computeVertexNormals();return g;};
  return {tri,quad,finish};
}
function plate(poly,depth,bevel=0.004){
  const b=Math.min(bevel,depth*0.32),small=offsetPolygon(poly,b),g=geometryBuilder();
  const loops=[small,poly,poly,small].map((p,i)=>p.map(q=>[q[0],q[1],[-depth/2,-depth/2+b,depth/2-b,depth/2][i]]));
  for(let k=0;k<3;k++)for(let i=0;i<poly.length;i++){const j=(i+1)%poly.length;g.quad(loops[k][i],loops[k][j],loops[k+1][j],loops[k+1][i]);}
  const cap=THREE.ShapeUtils.triangulateShape(small.map(p=>new THREE.Vector2(...p)),[]);
  for(const [a,b,c] of cap){g.tri(loops[0][c],loops[0][b],loops[0][a]);g.tri(loops[3][a],loops[3][b],loops[3][c]);}
  return g.finish();
}
function frame(outer,inner,depth,b=0.008){
  const g=geometryBuilder(),n=outer.length;
  const os=offsetPolygon(outer,b),is=offsetPolygon(inner,-b);
  const zs=[-depth/2,-depth/2+b,depth/2-b,depth/2];
  const O=[os,outer,outer,os].map((p,k)=>p.map(q=>[...q,zs[k]]));
  const I=[is,inner,inner,is].map((p,k)=>p.map(q=>[...q,zs[k]]));
  for(let k=0;k<3;k++)for(let i=0;i<n;i++){const j=(i+1)%n;g.quad(O[k][i],O[k][j],O[k+1][j],O[k+1][i]);g.quad(I[k][j],I[k][i],I[k+1][i],I[k+1][j]);}
  for(let i=0;i<n;i++){const j=(i+1)%n;g.quad(O[3][i],O[3][j],I[3][j],I[3][i]);g.quad(O[0][j],O[0][i],I[0][i],I[0][j]);}
  return g.finish();
}
function oct(w,h,c=0.035){return [[-w/2+c,-h/2],[w/2-c,-h/2],[w/2,-h/2+c],[w/2,h/2-c],[w/2-c,h/2],[-w/2+c,h/2],[-w/2,h/2-c],[-w/2,-h/2+c]];}

function group(parent,name,pos=[0,0,0],rot=[0,0,0]){const g=new THREE.Group();g.name=name;g.position.set(...pos);g.rotation.set(...rot.map(a=>a*Math.PI/180));parent.add(g);return g;}
function part(parent,name,geo,mat,pos=[0,0,0],rot=[0,0,0]){const p=createPart(name,geo,mat,{parent,position:pos,rotation:rot});p.name=name;return p;}
async function block(parent,name,s,pos,mat,r=0.06){return part(parent,name,await roundedBoxGeo(...s,Math.min(r,Math.min(...s)*0.3),{style:'chamfer'}),mat,pos);}
function panel(parent,name,w,h,d,c,pos,mat,rot=[0,0,0]){return part(parent,name,plate(oct(w,h,c),d,Math.min(d*0.25,0.025)),mat,pos,rot);}
function ring(parent,name,w,h,c,t,d,pos,mat,rot=[0,0,0]){return part(parent,name,frame(oct(w,h,c),oct(w-2*t,h-2*t,Math.max(0.025,c-t*0.6)),d,Math.min(t*0.12,d*0.18)),mat,pos,rot);}
function cyl(parent,name,r,d,pos,mat,rot=[0,0,0]){return part(parent,name,cylinderGeo(r,r,d,12),mat,pos,rot);}
function materialVariant(mat,name,i){const m=mat.clone();m.name=name;m.roughness+=i*0.002;return m;}
function beacon(parent,name,pos,m,s=1){const b=group(parent,name,pos);cyl(b,name+'_foot',0.11*s,0.07*s,[0,0.035*s,0],m.panelGray);part(b,name+'_case',plate(oct(0.19*s,0.23*s,0.025*s),0.18*s,0.014*s),m.panelGray,[0,0.18*s,0]);for(const side of [-1,1])panel(b,name+'_lens_'+side,0.13*s,0.13*s,0.012*s,0.008*s,[0,0.18*s,side*0.095*s],m.glowCool);return b;}
function mergeParts(parent){
  // Static surfaces can batch inside each semantic assembly without flattening its nodes.
  for(const c of [...parent.children])if(!(c instanceof THREE.Mesh))mergeParts(c);
  const buckets=new Map();
  for(const c of parent.children)if(c instanceof THREE.Mesh && !Array.isArray(c.material)){const key=c.material.uuid;if(!buckets.has(key))buckets.set(key,[]);buckets.get(key).push(c);}
  for(const meshes of buckets.values()){if(meshes.length<2)continue;const positions=[],normals=[],colors=[];let hasColors=false;
    for(const mesh of meshes){mesh.updateMatrix();let g=mesh.geometry.clone();g.applyMatrix4(mesh.matrix);if(g.index)g=g.toNonIndexed();const p=g.getAttribute('position'),n=g.getAttribute('normal'),co=g.getAttribute('color');hasColors=hasColors||!!co;for(let i=0;i<p.count;i++){positions.push(p.getX(i),p.getY(i),p.getZ(i));normals.push(n.getX(i),n.getY(i),n.getZ(i));if(co)colors.push(co.getX(i),co.getY(i),co.getZ(i));else colors.push(1,1,1);}g.dispose();}
    const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.setAttribute('normal',new THREE.Float32BufferAttribute(normals,3));if(hasColors)g.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));
    const combined=new THREE.Mesh(g,meshes[0].material);combined.name=parent.name+'_'+meshes[0].material.name.replace(/[^a-zA-Z0-9_-]/g,'_');parent.add(combined);for(const mesh of meshes)parent.remove(mesh);
  }
}

function beamBox(parent,name,a,b,w,d,mat){const delta=new THREE.Vector3(...b).sub(new THREE.Vector3(...a));const mesh=part(parent,name,boxGeo(w,delta.length(),d),mat,new THREE.Vector3(...a).add(new THREE.Vector3(...b)).multiplyScalar(.5).toArray());mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),delta.normalize());return mesh;}
function radialProfile(profile,n=12){const g=geometryBuilder();const loops=profile.map(([r,y])=>Array.from({length:n},(_,i)=>{const a=(i+.5)/n*Math.PI*2;return [Math.cos(a)*r,y,Math.sin(a)*r];}));for(let k=0;k<loops.length-1;k++)for(let i=0;i<n;i++){const j=(i+1)%n;if(profile[k][0]===0)g.tri(loops[k][i],loops[k+1][i],loops[k+1][j]);else if(profile[k+1][0]===0)g.tri(loops[k][i],loops[k+1][i],loops[k][j]);else g.quad(loops[k][i],loops[k+1][i],loops[k+1][j],loops[k][j]);}return g.finish();}


function screen(parent,name,w,h,pos,m,rot=[0,0,0]){const g=new THREE.PlaneGeometry(w,h);return part(parent,name,g,m.visor,pos,rot);}
function stroke(parent,name,pts,r,mat){for(let i=0;i<pts.length-1;i++){const a=new THREE.Vector3(...pts[i]),b=new THREE.Vector3(...pts[i+1]);const v=b.clone().sub(a);const p=part(parent,name+'_'+i,cylinderGeo(r,r,v.length(),8),mat,a.clone().add(b).multiplyScalar(.5).toArray());p.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),v.normalize());}}
async function datapad(parent,m,name='data_pad',scale=1){const p=group(parent,name);await block(p,'Strap',[.14,.022,.10],[0,.011,0],m.trim,.009);await block(p,'Slate pad base',[.15,.022,.10],[0,.028,0],m.panelGray,.012);await block(p,'Ivory raised bezel',[.142,.015,.092],[0,.044,0],m.panel,.012);await block(p,'Blue inset screen',[.105,.003,.065],[0,.053,0],m.visor,.004);for(const x of [-.058,.058])for(const z of [-.035,.035])await block(p,'Orange corner '+x+z,[.025,.012,.022],[x,.05,z],m.accent,.003);for(let i=0;i<3;i++)await block(p,'Screen data bar '+i,[.05-i*.009,.0015,.004],[-.018+i*.004,.055,-.020+i*.010],i===2?m.glowWarm:m.glowCool,.0004);p.scale.setScalar(scale);return p;}
function rtrack(n,arr){return rotationTrack(n,arr.map(([time,rotation])=>({time,rotation})),'EASE_IN_OUT');}
function ptrack(n,arr){return positionTrack(n,arr.map(([time,position])=>({time,position})),'EASE_IN_OUT');}

const meta={name:'pebble',reference:'docs/style/references/generated/g05-pebble-box-buddy.jpg'};

async function build(){const root=createRoot('pebble'),m=styleMaterials();
const chassis=group(root,'chassis');await block(chassis,'Charcoal undercarriage',[.43,.12,.33],[0,.14,0],m.panelGray,.035);
for(const side of [-1,1]){const track=group(root,side<0?'track_l':'track_r',[0,.102,side*.19]);
// Closed oval track section with thick inner wall; radial axes are X and Y.
const outer=[],inner=[];const N=20;for(let i=0;i<N;i++){const a=i/N*Math.PI*2;outer.push([Math.cos(a)*.105+(Math.cos(a)>=0?.14:-.14),Math.sin(a)*.102]);inner.push([Math.cos(a)*.061+(Math.cos(a)>=0?.14:-.14),Math.sin(a)*.061]);}
part(track,'Continuous charcoal tread belt',frame(outer,inner,.11,.006),m.trim);
for(let i=0;i<24;i++){const a=i/24*Math.PI*2,x=Math.cos(a)*.108+(Math.cos(a)>=0?.14:-.14),y=Math.sin(a)*.105;const lug=await block(track,'Tread pad '+i,[.045,.017,.12],[x,y,0],m.panelGray,.004);lug.rotation.z=a-Math.PI/2;}
for(const x of [-.14,.14]){cyl(track,'Orange drive hub '+x,.073,.118,[x,0,0],m.accent,[90,0,0]);cyl(track,'Dark hub inset '+x,.054,.124,[x,0,0],m.panelGray,[90,0,0]);}
await block(track,'Orange track side armor',[.15,.066,.014],[0,0,side*.064],m.accent,.012);
}
const body=group(root,'body',[0,.29,0]);await block(body,'Ivory rounded cube shell',[.32,.235,.34],[0,.03,0],m.panel,.045);
for(const s of [-1,1])await block(body,'Orange body cheek '+s,[.23,.19,.028],[0,.025,s*.168],m.accent,.018);
await block(body,'Lower graphite belly',[.14,.06,.22],[.105,-.075,0],m.panelGray,.018);
for(const z of [-.095,.095])await block(body,'Front service screw '+z,[.008,.018,.018],[.162,.055,z],m.panelGray,.003);
const neck=group(body,'neck',[0,.167,0]);await block(neck,'Short neck pedestal',[.065,.045,.09],[0,0,0],m.trim,.008);
const head=group(neck,'head',[.015,.092,0]);await block(head,'Ivory rounded head',[.20,.17,.28],[0,0,0],m.panel,.036);
for(const s of [-1,1])cyl(head,'Orange ear disc '+s,.047,.026,[0,0,s*.148],m.accent,[90,0,0]);
panel(head,'Dark face rim',.244,.139,.018,.035,[.102,0,0],m.trim,[0,90,0]);
screen(head,'screen_face',.22,.12,[.113,0,0],m,[0,90,0]);
const eyes=group(head,'face_default',[.115,0,0]);for(const z of [-.052,.052]){const pts=[];for(let i=0;i<=8;i++){const a=i/8*Math.PI;pts.push([0,Math.sin(a)*.025-.005,z+Math.cos(a)*.018]);}stroke(eyes,'Happy eye '+z,pts,.0034,m.glowCool);}
const antenna=group(head,'antenna',[-.025,.092,0]);cyl(antenna,'Short antenna stalk',.006,.052,[0,.022,0],m.panelGray);cyl(antenna,'Single cyan beacon',.013,.027,[0,.061,0],m.glowCool);
for(const side of [-1,1]){const suffix=side<0?'l':'r';const arm=group(body,'arm_'+suffix,[.02,.075,side*.19]);
cyl(arm,'Shoulder socket',.037,.035,[0,0,0],m.panelGray,[90,0,0]);
await block(arm,'Ivory upper link',[.065,.055,.082],[.025,-.017,side*.045],m.panel,.014);
const elbow=group(arm,'elbow_'+suffix,[.07,-.045,side*.075]);cyl(elbow,'Elbow pivot',.029,.07,[0,0,0],m.trim,[90,0,0]);
await block(elbow,'Ivory forearm',[.09,.045,.049],[.049,0,0],m.panel,.012);
const grip=group(elbow,'grip_'+suffix,[.098,0,0]);await block(grip,'Gripper palm',[.045,.047,.057],[.015,0,0],m.panelGray,.010);
for(const finger of [-1,1]){const f=group(grip,'finger_'+suffix+'_'+(finger<0?'a':'b'),[.03,0,finger*.023]);await block(f,'Two finger jaw',[.050,.025,.022],[.020,0,0],m.trim,.006);}
if(side>0){const nozzle=group(elbow,'nozzle_r',[.06,.030,0]);cyl(nozzle,'Wrist air nozzle',.012,.045,[.008,0,0],m.panelGray,[0,0,90]);cyl(nozzle,'Nozzle outlet',.008,.003,[.032,0,0],m.trim,[0,0,90]);}
}
mergeParts(root);defineBudget({triangles:BUDGETS.character},root);return root;}
function animate(){const R=(n,angles,d=2)=>rtrack(n,angles.map((a,i)=>[i*d/(angles.length-1),a]));const P=(n,pts,d=2)=>ptrack(n,pts.map((p,i)=>[i*d/(pts.length-1),p]));const spin=(n,s=1)=>R(n,[[0,0,0],[0,s*90,0],[0,s*180,0],[0,s*270,0],[0,s*360,0]]);const clip=(n,tr,loop=true,d=2)=>createClip(n,d,tr,{loop});return [
clip('Idle',[P('body',[[0,.29,0],[0,.294,0],[0,.29,0]]),R('head',[[0,0,-2],[0,0,2],[0,0,-2]])]),
clip('Drive',[R('body',[[0,0,-3],[0,0,3],[0,0,-3]]),R('track_l',[[0,0,0],[0,0,1],[0,0,0]]),R('track_r',[[0,0,0],[0,0,-1],[0,0,0]])]),
clip('TurnInPlace',[spin('chassis'),spin('body'),R('track_l',[[0,0,0],[0,0,2],[0,0,0]]),R('track_r',[[0,0,0],[0,0,-2],[0,0,0]])]),
clip('Happy',[R('body',[[0,0,0],[8,0,-5],[-8,0,5],[0,0,0]]),spin('antenna'),R('arm_l',[[0,0,0],[30,0,25],[0,0,0]])]),
clip('Worried',[R('head',[[0,0,0],[0,0,-12],[0,0,0]]),P('body',[[0,.29,0],[-.035,.27,0],[0,.29,0]])],false),
clip('Hide',[P('chassis',[[0,0,0],[-.12,0,0],[-.12,0,0]]),P('body',[[0,.29,0],[-.12,.25,0],[-.12,.25,0]]),P('head',[[.015,.092,0],[-.02,.06,0],[-.02,.06,0]])],false),
clip('Clean',[R('arm_r',[[0,0,12],[0,0,42],[0,0,12]]),R('elbow_r',[[0,20,0],[0,-25,0],[0,20,0]]),R('head',[[0,-10,0],[0,10,0],[0,-10,0]])]),
clip('Grip',[R('finger_l_a',[[0,-20,0],[0,10,0],[0,-20,0]]),R('finger_l_b',[[0,20,0],[0,-10,0],[0,20,0]]),R('finger_r_a',[[0,-20,0],[0,10,0],[0,-20,0]]),R('finger_r_b',[[0,20,0],[0,-10,0],[0,20,0]])],false),
clip('HeadTilt',[R('head',[[0,0,0],[15,0,-8],[0,0,0]])],false),
clip('Reboot',[P('body',[[0,.29,0],[0,.26,0],[0,.30,0],[0,.29,0]]),R('head',[[0,0,0],[0,0,-18],[0,0,4],[0,0,0]])],false),
clip('Charge',[P('body',[[0,.29,0],[0,.275,0],[0,.275,0]]),R('antenna',[[0,0,0],[0,0,25],[0,0,25]])],false),
clip('Point',[R('arm_r',[[0,0,0],[0,0,50],[0,0,50]]),R('head',[[0,0,0],[0,-15,0],[0,-15,0]])],false)
];}
